class TreeNode:
    def __init__(self, data=0, left=None, right=None, random=None):
        self.data = data
        self.left = left
        self.right = right
        self.random = random

def cloneTree(root):
    if not root:
        return None

    node_map = {}

    def clone(node):
        if not node:
            return None
        if node in node_map:
            return node_map[node]
        new_node = TreeNode(node.data)
        node_map[node] = new_node
        new_node.left = clone(node.left)
        new_node.right = clone(node.right)
        new_node.random = clone(node.random)
        return new_node

    return clone(root)
